interface Validator {
    default boolean isValidAndNotEmpty(String input) {
        return logAndCheck(input) && !input.isEmpty();
    }

    default boolean isValidAndTrimmed(String input) {
        return logAndCheck(input) && input.equals(input.trim());
    }

    private boolean logAndCheck(String input) { // NIE czesc publicznego API
        return input != null;
    }
}

